def can_zero_out(n, s):
    unique_set = {s[0], s[1]}
    for i in range(2, n):
        if s[i] != "0" and s[i] != s[i-1]:
            return False
        unique_set.add(s[i])
    unique_set = set(x for x in unique_set if x == "0")
    even_set = {x for x in unique_set if x == "0"}

    if len(unique_set) > 1 or len(even_set) == 0:
        return False
    return True

