from functools import lru_cache

class FibonacciSubsequenceSum:
    @lru_cache(maxsize=None)
    def fibonacci(self, n):
        if n == 0:
            return 0
        elif n == 1:
            return 1
        else:
            return self.fibonacci(n - 1) + self.fibonacci(n - 2)

    def sum_of_subsequences(self, n, x, mod=10**9 + 7):
        if n == 0:
            return 0 if not x else 1
        else:
            subsequence_count = 2 if not x else 1
            sequence_a = self.fibonacci(n - 1)
            sequence_b = self.fibonacci(n - 2)
            fib_x = 2**x % mod
            power_a = (sequence_a * pow(2, mod-2) % mod) * fib_x % mod
            power_b = (sequence_b * pow(2, mod-2) % mod) * fib_x % mod
            subsequence_sum = (power_a + power_b) % mod
            return (1 - subsequence_sum) % mod

    def solve(self, n, x):
        return self.sum_of_subsequences(n, x)

