def calculate_cost(s, length):
    # Base cases
    if length == 0:
        return 0
    if length == 1:
        return s.count('1')

    # Initialize memoization dictionary
    memo = {}

    # Helper function to calculate cost recursively
    def memoized_cost(i, j):
        if (i, j) in memo:
            return memo[(i, j)]

        if i == 0:
            memo[(i, j)] = 1 * int(s[j-1])
        elif i == 1:
            memo[(i, j)] = 1 * int(s[j-1]) + 1
        else:
            memo[(i, j)] = (int(s[j-1]) + memoized_cost(i-1, j-2)) % 1000000007
            memo[(i, j)] = (memo[(i, j-1)] + memo[(i, j-2)] * int(s[j-1])) % 1000000007

        memo[(i, j)] = int((memo[(i, j)] * (500000003 - 250000002 % 1000000007) + 250000002 * int(s[j-1]))) % 1000000007
        return memo[(i, j)] % 1000000007

    # Calculate cost for each subsequence of length 1 to n
    cost = sum(memoized_cost(length - i, length) for i in range(1, length + 1)) % 1000000007

    return cost

