import sys

def find_max_strength(n, q, dato, corona):
    # Memoization table to store the maximum strength after each query
    memo = [[0] * (1 << n) for _ in range(q + 1)]
    memo[0] = [[-inf] * (1 << n) for _ in range(q + 1)]

    def dp(current_query, horses_joined):
        nonlocal memo
        if current_query == q:
            return 0, (1 << n) - 1

        if memo[current_query][horses_joined] != [-inf] * (1 << n):
            return memo[current_query][horses_joined]

        max_strength = -inf
        for i in range(n):
            if not (2 << i) & horses_joined:
                strength, horses_joined_mask = dp(current_query + 1, horses_joined | (1 << i))
                total_strength = dato[i] * corona[i] + strength
                if total_strength > max_strength:
                    max_strength = total_strength
            else:
                total_strength = dato[i] * corona[i]
                if total_strength > max_strength:
                    max_strength = total_strength

        memo[current_query][horses_joined] = [max_strength, horses_joined_mask]
        return memo[current_query][horses_joined]

    (_, horses_joined_mask) = dp(0, 0)
    horses_joined = sum(horses_joined_mask)
    s = 0
    for i in range(n):
        if not (2 << i) & horses_joined_mask:
            ati = dato[i]
            hti = corona[i]
            s += ati * hti
    return s


