from collections import defaultdict

def merge_queries(queries):
    merged_queries = []
    for query in queries:
        base_decompositions = defaultdict(int)
        for seq in query.split(", "):
            for number in seq:
                if number in base_decompositions:
                    base_decompositions[number] += 1
                else:
                    base_decompositions[number] = 1
        if not any(base_decomposition % 2 != 0 for base_decomposition in base_decompositions.values()):
            merged_queries.append("1")
        else:
            merged_queries.append("0")
    return merged_queries

