        self.name = name
        self.Friday = Friday
        self.Saturday = Saturday

def optimal_clubbing(happinessFriday, happinessSaturday, budget):
    clubs = []
    for i in range(len(happinessFriday)):
        center, Friday, Saturday = i, tuple([happinessFriday[i]]), tuple([happinessSaturday[i]])
        if is_valid_subset((2, Friday, Saturday), clubs, budget):
            clubs.append((center, Friday, Saturday))
    return sorted(clubs, key=lambda x: -sum(x[1] + x[2]))

def solve(matrixFriday, matrixSaturday, budget):
