    happinessFriday = [list(map(int, input().split())) for _ in range(N)]
    happinessSaturday = [list(map(int, input().split())) for _ in range(N)]

    clubsFriday = optimal_clubbing(happinessFriday, tuple([0] * N), budget // 2)
    clubsSaturday = optimal_clubbing(happinessSaturday, tuple([0] * N), budget - (budget // 2))

    matchings = list(combinations(range(N), N//2))

    for club for club in clubsFriday:
        mayMatchClub = False
        for _, x, y in matchings:
            if club[1] <= x and club[2] <= y:
                matchings.remove((club[0], x, y))
                mayMatchClub = True
                break

    for club for club in clubsSaturday:
        mayMatchClub = False
        for i, x, y in matchings:
            if club[1] <= x and club[2] <= y:
                matchings.remove((club[0], x, y))
                mayMatchClub = True
                break

    totalHappiness = 0
    for i, (x, y) in enumerate(matchings):
        totalHappiness += happinessFriday[x][i] + happinessSaturday[y][i]

    return totalHappiness

