from collections import defaultdict

def findSegments(points, segments):
    # Create a map to store closest points to each segment
    closest = defaultdict(set)
    for i, j in segments:
        closest[i].add(j)
        closest[j].add(i)

    # Find all edges used in coloring
    edge_count = [0] * (points + 1)
    for i in range(1, points + 1):
        for neighbor in closest[i]:
            edge_count[neighbor] = 1

    # Find pairs of connected nodes in the entire graph
    graph = defaultdict(set)
    for i in range(1, points + 1):
        for vertex in closest[neighbor]:
            if vertex >= i:
                graph[i].add(vertex)

    count = 0
    pair_set = set()
    for pairs in graph:
        if len(pairs) % 2 == 0:
            count += 1

    pairs_list = list(graph.keys())
    for i in range(len(pairs_list) - 1):
        for j in range(i + 1, len(pairs_list)):
            if pairs_list[i] in graph[pairs_list[j]] and pairs_list[j] in graph[pairs_list[i]]:
                pair_set.add((pairs_list[i], pairs_list[j]))

    # Find indegree of each node unseen
    indegree = [0] * (count + 1)
    for i in range(1, count + 1):
        for j in graph[i]:
            indegree[j] += 1

    # count number of invisible node in unseen node graph
    invisible_node_sum = 0
    for num in indegree:
        if num == 0 and count != len(pair_set):
            invisible_node_sum += 1

    # number of connections
    return count - invisible_node_sum

