import math

def can_reach_zero(points_str):
    n = len(points_str)
    bits = [0] * n
    for i, point in enumerate(points_str):
        bits[i] = int(point)

    for i, point in enumerate(bits):
        if point:
            for j in range(i + 1, n):
                if (bits[i] & bits[j]) > (bits[i] ^ points_str[j]):
                    bits[i] = points_str[j]
            if bits[i] == 0:
                break
            num_equivalent = bin(bits[i]).count('1')
            if num_equivalent % 2 == 1:
                return False
        if i == n - 1:
            return False

    for i in range(n):
        remaining_positions = bin(bits[i]).count('1') - 1
        if bits[i] != 0:
            remaining_positions -= 1
        if i == n - 1 and (n - 1 - bits[i]) % 2 == 1:
            remaining_positions -= 1
        if (bits[i] > 0 and remaining_positions < bits[i]) or (bits[i] < 0 and remaining_positions > bits[i]):
            return False

    return True

def main():
    n = int(input())
    points = [str(input()) for _ in range(n)]
    return "YES" if can_reach_zero(points) else "NO"

