from typing import List

def maxStrangeSetCost(n: int, a: List[int], b: List[int]) -> int:
    A = sorted((a.val, -a.val) for a in a)
    sets = []

    for val, neg in A:
        while sets and (neg is not None and sets[-1][0] >= (-neg)):
            sets.pop()

        if not sets:
            sets.append((-val, val))
        else:
            if neg is not None:
                sets.append((neg, sets[-1][1] + (neg > 0)))
            else:
                sets.append((sets[-1][0], val + sets[-1][1]))

    # Calculate the maximum cost by considering all strange sets and their costs
    return max(sum(sets[j][0] * b[j] for j in range(len(sets))) for _ in range((1 << n)))

