def build_tree(edges):
    adj = [[] for _ in range(len(edges) + 1)]
    in_degree = [0] * (len(edges) + 1)

    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
        in_degree[u] += 1
        in_degree[v] += 1

    return adj, in_degree

def reverse_tree(adj):
    rev_adj = [[] for _ in adj]
    for u in adj:
        for v in u:
            rev_adj[v].append(u)
    return rev_adj

def calculate_bino(adj, depth):
    counter = {}

    def dfs(node):
        for v in adj[node]:
            if v not in counter:
                counter[v] = sum(counter[u] for u in adj[v] if u < node or node in u) + 1
            for idx in range(len(v)):
                counter[v] -= 1
                if not counter[v[idx]]:
                    del counter[v[idx]]
        return len(adj[node])

    if depth % 2 == 1:
        return dfs(1)
    else:
        logistic_sum, total_sum = 0, 1
        for node in adj:
            for u in node:
                if u not in counter:
                    counter[u] = total_sum + 1
                    total_sum *= 2
                logistic_sum += total_sum
        return (total_sum // 2 - logistic_sum) % mod

def dfs2(node, current_depth):
    edges, in_degree = build_tree(edges)
    rev_edges = reverse_tree(edges)
    answer = calculate_bino(edges, current_depth + 1)
    for child in rev_edges[node]:
        answer = (answer * calculate_bino(rev_edges, current_depth)) % mod
    return (answer + (3 - binomial_tree[current_depth][node]) * answer) % mod

def calculate_answer(k):
    binomial_tree = [[0] * (k) for _ in range(k + 1)]
    for i in range(k + 1):
        for j in range(i + 1):
            binomial_tree[i][j] = calculate_bino(1 + j, i - j)

    answer = 0
    for curr_path_depth in range(k):
        for next_path_depth in range(k - curr_path_depth):
            answer = (answer + binomial_tree[curr_path_depth + 1][next_path_depth] * binomial_tree[next_path_depth + 1][curr_path_depth + next_path_depth + 1]) % mod
        answer = (answer * dfs2(1, curr_path_depth)) % mod

    return answer % mod

