from collections import defaultdict

def find_segments_to_erase(n, m, segments):
    # Create a dictionary to keep track of connected components
    unions = defaultdict(lambda: (-1, -1))

    def find(u):
        if unions[u][0] == -1:
            return u
        unions[u] = (find(unions[u][0]), find(unions[u][1]))
        return unions[u][0]

    def union(u, v):
        root_u, root_v = find(u), find(v)
        if root_u != root_v:
            if unions[root_u] > unions[root_v]:
                root_u, root_v = root_v, root_u
            unions[root_u] = (root_u, root_v)

    # Find first segment to check
    segment = segments[0]
    u, v = segment
    union(u, v)

    # Process remaining segments, removing those that don't meet the conditions
    for i in range(1, len(segments)):
        u, v = segments[i]
        if find(u) != find(v):
            union(u, v)
        else:
            # If both points of the segment are in the same connected component
            return " impossible"

    # Return all segments that help if possible
    result = []
    for i in range(m):
        if unions[find(segments[i][0])][0] != unions[find(segments[i][1])][0]:
            result.append(steps[i + 1])
    return (len(result), " ".join(map(str, result)))

