    lines = [sys.stdin.readline().split() for _ in range(n)]

    max_x, max_y, line_a, line_b, line_c = min_distance(lines)

    def distance(x, y):
        if y == 0:
            return abs(x) + abs(line_a * x + line_b + line_c) / (line_a**2 + line_b**2)**0.5
        else:
            slope = -(line_b / line_a)
            line_x = -slope * x - slope * line_c - line_b / slope
            return abs(x - line_x) + abs(y) / (slope**2 + 1)

    max_distance = float('-inf')
    for x in range(-int(max_x), int(max_x) + 1):
        for y in range(-int(max_y), int(max_y) + 1):
            dist = distance(x, y)
            max_distance = max(max_distance, dist)

