    for test_case in test_cases:
        n = test_case[0]
        array = test_case[1].split()
        array = list(map(int, array))

        # Count occurrences of each number in the array
        occurrences = {}
        for num in array:
            if num in occurrences:
                occurrences[num] += 1
            else:
                occurrences[num] = 1

        # If certain number of occurrences are greater than 1, subtract 1 from occurrences to enable split potential in subsequence
        for num in occurrences:
            if occurrences[num] > 1:
                occurrences[num] -= 1

        total_good_indices = 0
        # Check each index
        for i in range(n):
            for j in range(n):
                if i != j and array[i] == array[j]:
                    total_good_indices += 1
                    break

        max_good = max(max_good, total_good_indices)

